{
  "items": [
    {
      "name": "one_le_pow_mul_abs_eval_div",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {K : Type u_1} [inst : Field K] [inst_1 : LinearOrder K] [IsStrictOrderedRing K] {f : Polynomial ℤ} {a b : ℤ},\n  0 < b →\n    Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f) ≠ 0 →\n      1 ≤ ↑b ^ f.natDegree * |Polynomial.eval (↑a / ↑b) (Polynomial.map (algebraMap ℤ K) f)|"
    },
    {
      "name": "DenomsClearable",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "definition",
      "type": "{R : Type u_1} →\n  {K : Type u_2} → [inst : Semiring R] → [inst_1 : CommSemiring K] → R → R → ℕ → Polynomial R → (R →+* K) → Prop"
    },
    {
      "name": "denomsClearable_of_natDegree_le",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {K : Type u_2} [inst : Semiring R] [inst_1 : CommSemiring K] {i : R →+* K} {b : R} {bi : K} (N : ℕ)\n  (a : R), bi * i b = 1 → ∀ (f : Polynomial R), f.natDegree ≤ N → DenomsClearable a b N f i"
    },
    {
      "name": "Liouville.exists_pos_real_of_irrational_root",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "theorem",
      "type": "∀ {α : ℝ},\n  Irrational α →\n    ∀ {f : Polynomial ℤ},\n      f ≠ 0 →\n        Polynomial.eval α (Polynomial.map (algebraMap ℤ ℝ) f) = 0 →\n          ∃ A, 0 < A ∧ ∀ (a : ℤ) (b : ℕ), 1 ≤ (↑b + 1) ^ f.natDegree * (|α - ↑a / (↑b + 1)| * A)"
    },
    {
      "name": "denomsClearable_C_mul_X_pow",
      "module_name": "Mathlib.Algebra.Polynomial.DenomsClearable",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {K : Type u_2} [inst : Semiring R] [inst_1 : CommSemiring K] {i : R →+* K} {b : R} {bi : K} {N : ℕ}\n  (a : R), bi * i b = 1 → ∀ {n : ℕ} (r : R), n ≤ N → DenomsClearable a b N (Polynomial.C r * Polynomial.X ^ n) i"
    },
    {
      "name": "Liouville.transcendental",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.Basic",
      "kind": "theorem",
      "type": "∀ {x : ℝ}, Liouville x → Transcendental ℤ x"
    },
    {
      "name": "LiouvilleWith",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "definition",
      "type": "ℝ → ℝ → Prop"
    },
    {
      "name": "LiouvilleWith.ne_cast_int",
      "module_name": "Mathlib.NumberTheory.Transcendental.Liouville.LiouvilleWith",
      "kind": "theorem",
      "type": "∀ {p x : ℝ}, LiouvilleWith p x → 1 < p → ∀ (m : ℤ), x ≠ ↑m"
    }
  ]
}
